<?php declare(strict_types=1); require_once __DIR__.'/../lib_auth.php'; require_login(); $y=(int)date('Y'); ?>
<div class="container-fluid px-2 px-md-3 py-3"><div class="mb-3"><h3 class="font-weight-bold mb-1">Bukti Laporan Kemkes</h3><p class="text-muted mb-0">Matrix bukti pelaporan per bulan.</p></div><div id="bkAlert"></div>
<div class="card card-soft mb-3"><div class="card-body py-2"><div class="form-inline"><label class="mr-2 font-weight-bold">Tahun:</label><select id="bkTahun" class="form-control form-control-sm"><?php for($i=$y-3;$i<=$y+1;$i++): ?><option <?=$i===$y?'selected':''?>><?=$i?></option><?php endfor;?></select></div></div></div>
<div class="card card-soft"><div class="card-header card-soft-header-primary d-flex justify-content-between align-items-center"><span>Matrix Pelaporan Kemkes Tahun <span id="bkYearTitle"><?=$y?></span></span><button class="btn btn-primary btn-sm" data-toggle="modal" data-target="#bkUpload"><i class="fas fa-upload"></i> Upload Bukti</button></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-sm text-center" id="bkTable"><thead><tr><th style="width:30px">No.</th><th class="text-left">Jenis Laporan</th><?php foreach(['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'] as $b): ?><th style="width:48px"><?=$b?></th><?php endforeach; ?></tr></thead><tbody></tbody></table></div></div></div></div>
<div class="modal fade" id="bkUpload" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form id="bkForm" enctype="multipart/form-data"><div class="modal-header"><h5 class="modal-title">Upload Bukti Laporan</h5><button type="button" class="close" data-dismiss="modal">&times;</button></div><div class="modal-body"><div class="form-group"><label>Bulan Laporan</label><select name="bulan" id="bkBulan" class="form-control"><?php for($i=1;$i<=12;$i++): ?><option value="<?=$i?>"><?=date('F',mktime(0,0,0,$i,1))?></option><?php endfor;?></select></div><div class="form-group"><label>Tahun Laporan</label><input name="tahun" id="bkUploadTahun" type="number" class="form-control" value="<?=$y?>"></div><div class="form-group"><label>Jenis Laporan</label><select name="jenis_laporan" id="bkJenis" class="form-control"></select></div><div class="form-group"><label>File Bukti (gambar/PDF)</label><input name="bukti" id="bkFile" type="file" class="form-control-file" accept="image/*,application/pdf"><button type="button" id="bkPaste" class="btn btn-outline-secondary btn-sm mt-2"><i class="fas fa-clipboard"></i> Tempel Clipboard</button><div class="mt-2" id="bkImagePreviewWrap" style="display:none"><img id="bkImagePreview" style="max-width:100%;max-height:240px" class="img-thumbnail"></div><small class="text-muted d-block mt-1">Tempel hanya berlaku untuk gambar yang tersimpan di clipboard.</small></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-dismiss="modal">Batal</button><button class="btn btn-primary">Upload / Update</button></div></form></div></div></div>
<div class="modal fade" id="bkView" tabindex="-1"><div class="modal-dialog modal-xl"><div class="modal-content"><div class="modal-header"><h5 class="modal-title" id="bkViewTitle">Bukti Laporan</h5><button type="button" class="close" data-dismiss="modal">&times;</button></div><div class="modal-body text-center"><div id="bkPreview"></div><small class="text-muted" id="bkUploaded"></small></div></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const api='api/bukti-laporan-kemkes.php',names=['INM','IKP','PPRA','HAIS','MPDN','Simatneo','SITB','SIGIZI Pelita kesmas','SIHA','SIGA'],id=x=>document.getElementById(x),months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];const preview=f=>{if(f&&f.type.startsWith('image/')){id('bkImagePreview').src=URL.createObjectURL(f);id('bkImagePreviewWrap').style.display='block';}};async function load(){const y=id('bkTahun').value,r=await fetch(api+'?tahun='+y),j=await r.json();if(!j.ok)throw Error(j.message);id('bkYearTitle').textContent=y;id('bkJenis').innerHTML=names.map(n=>'<option>'+n+'</option>').join('');const tb=id('bkTable').querySelector('tbody');tb.innerHTML=names.map((n,i)=>'<tr><td>'+(i+1)+'</td><td class="text-left">'+n+'</td>'+Array.from({length:12},(_,k)=>{const v=j.data[k+1]?.[n];return '<td>'+(v?'<button class="btn btn-link btn-sm text-success p-0 bk-view" data-title="'+n+' - '+months[k]+' '+y+'" data-path="'+v.file_path+'" data-time="'+v.uploaded_at+'"><i class="fas fa-check-circle"></i></button>':'<span class="text-muted">-</span>')+'</td>'}).join('')+'</tr>').join('');document.querySelectorAll('.bk-view').forEach(b=>b.onclick=()=>{id('bkViewTitle').textContent='Bukti '+b.dataset.title;id('bkUploaded').textContent='Upload/update: '+b.dataset.time;const p=b.dataset.path;id('bkPreview').innerHTML=/\.pdf$/i.test(p)?'<iframe src="'+p+'" style="width:100%;height:70vh;border:0"></iframe>':'<img src="'+p+'" style="max-width:100%;max-height:70vh">';$('#bkView').modal('show')})}id('bkTahun').onchange=()=>load().catch(e=>id('bkAlert').textContent=e.message);id('bkFile').onchange=()=>preview(id('bkFile').files[0]);id('bkPaste').onclick=async()=>{try{const items=await navigator.clipboard.read();for(const it of items){const t=it.types.find(x=>x.startsWith('image/'));if(t){const f=new File([await it.getType(t)],'clipboard.png',{type:t});const d=new DataTransfer();d.items.add(f);id('bkFile').files=d.files;preview(f);return;}}throw Error('Clipboard tidak berisi gambar.')}catch(e){id('bkAlert').textContent='Izinkan akses clipboard browser, lalu coba lagi.'}};id('bkForm').onsubmit=async e=>{e.preventDefault();const r=await fetch(api,{method:'POST',body:new FormData(e.target)}),j=await r.json();if(!j.ok){id('bkAlert').textContent=j.message;return}$('#bkUpload').modal('hide');e.target.reset();id('bkImagePreviewWrap').style.display='none';await load()};load().catch(e=>id('bkAlert').textContent=e.message)});</script>
